 useEffect(()=>{load();},[]);
 useEffect(()=>{const styleRanges=()=>document.querySelectorAll<HTMLInputElement>('input[type=range]').forEach(input=>{const min=Number(input.min||0),max=Number(input.max||100),percent=Math.max(0,Math.min(100,(Number(input.value)-min)/Math.max(.0001,max-min)*100));input.style.setProperty('--range-progress',`${percent}%`)});styleRanges();document.addEventListener('input',styleRanges);const observer=new MutationObserver(styleRanges);observer.observe(document.getElementById('root')!,{childList:true,subtree:true});return()=>{document.removeEventListener('input',styleRanges);observer.disconnect()}},[]);
 useEffect(()=>{if(!job?.id)return;let closed=false;let timer:any;const poll=async()=>{try{const j=await api(`/api/jobs/${job.id}`);if(closed)return;setJob({...j,id:job.id,type:job.type});if(['completed','complete','done','succeeded'].includes(j.status)){setBusy(false);await load();if(job.type==='generate'){const pid=j.result?.projectId||j.result?.id||j.projectId;if(pid){const ready=await api(`/api/projects/${pid}`);setProject(ready);setPlaying(false);seek(0);if(preferencesRef.current.workflow?.autoOpenGenerated!==false){setAudio(ready.audio);setLevelTab('Studio');setPage('Studio');}else{setPage('Levels');setLevelsView('library');if(!preferencesRef.current.storage?.rememberImportedAudio)setAudio(null);}setNotice('Your project is ready. Open it in Studio to inspect, edit and export.');}}else setNotice(job.type==='continuation'?'Continuation draft ready. Review it in Studio and accept only when it fits.':job.type==='composition'?'Full-map phrase and lighting conditioning is ready.':job.type==='playlist'?'Playlist maps imported and local training completed.':'Training finished. The local model is ready for the next generation.');return;}if(['failed','error','cancelled'].includes(j.status)){setBusy(false);if(j.error)setError(j.error);return;}timer=setTimeout(poll,1300);}catch(e:any){setError(e.message);setBusy(false);}};poll();return()=>{closed=true;clearTimeout(timer);};},[job?.id]);
